INSERT INTO recurso_software (id_recurso, id_software) SELECT r.id_recurso, s.id_software FROM recursos_ct r JOIN carro c ON c.id_carro = r.id_carro JOIN software s ON s.nombre_software IN ('Qt Creator', 'Visual Studio Code', 'Microsoft Office') WHERE c.nombre_carro = 'C4';
INSERT INTO recurso_software (id_recurso, id_software) SELECT r.id_recurso, s.id_software FROM recursos_ct r JOIN carro c ON c.id_carro = r.id_carro JOIN software s ON s.nombre_software = 'SQL Server Management Studio' WHERE c.nombre_carro = 'C4' AND r.numero_equipo <= 5;
INSERT INTO recurso_software (id_recurso, id_software) SELECT r.id_recurso, s.id_software FROM recursos_ct r JOIN carro c ON c.id_carro = r.id_carro JOIN software s ON s.nombre_software = 'DBeaver' WHERE c.nombre_carro = 'C4' AND r.numero_equipo > 5;
INSERT INTO recurso_software (id_recurso, id_software) SELECT r.id_recurso, s.id_software FROM recursos_ct r JOIN carro c ON c.id_carro = r.id_carro JOIN software s ON s.nombre_software IN ('Oracle VirtualBox', 'Visual Studio Code', 'Microsoft Office') WHERE c.nombre_carro = 'C5';
