INSERT INTO recurso_software (id_recurso, id_software) SELECT r.id_recurso, s.id_software FROM recursos_ct r JOIN carro c ON c.id_carro = r.id_carro JOIN software s ON s.nombre_software IN ('Qt Creator', 'Visual Studio Code', 'Microsoft Office') WHERE c.nombre_carro = 'C1';
INSERT INTO recurso_software (id_recurso, id_software) SELECT r.id_recurso, s.id_software FROM recursos_ct r JOIN carro c ON c.id_carro = r.id_carro JOIN software s ON s.nombre_software IN ('Microsoft Office', 'SQL Server Management Studio', 'DBeaver') WHERE c.nombre_carro = 'C2';
